param(
  [switch]$SkipBuild
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$Backup = Join-Path $Root ".orcaly-backups\padronizar-checkouts-$Stamp"
$Utf8 = New-Object System.Text.UTF8Encoding($false)

function Full([string]$Path) {
  Join-Path $Root ($Path -replace "/", "\")
}

function Backup-File([string]$Path) {
  $Source = Full $Path

  if (-not (Test-Path -LiteralPath $Source)) {
    return
  }

  $Destination = Join-Path $Backup ($Path -replace "/", "\")
  New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
  Copy-Item -LiteralPath $Source -Destination $Destination -Force
}

function Write-Base64File(
  [string]$Path,
  [string]$Base64
) {
  $Target = Full $Path
  New-Item -ItemType Directory -Force -Path (Split-Path $Target -Parent) | Out-Null

  $Text = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String($Base64)
  )

  [IO.File]::WriteAllText(
    $Target,
    $Text.TrimEnd() + "`n",
    $Utf8
  )

  Write-Host "[OK] $Path" -ForegroundColor Green
}

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
  throw "Execute este script na raiz do projeto Orcaly."
}

$Branch = (& git branch --show-current 2>$null | Out-String).Trim()

if ($Branch -ne "feature/asaas-sandbox") {
  throw "Branch atual: $Branch. Execute na branch feature/asaas-sandbox."
}

$Required = @(
  "components/subscription/MercadoPagoSubscriptionCheckout.tsx",
  "components/checkout/SignupCheckout.tsx",
  "components/checkout/CheckoutClient.tsx",
  "lib/payments/checkout-service.ts"
)

foreach ($File in $Required) {
  if (-not (Test-Path -LiteralPath (Full $File))) {
    throw "Arquivo necessario nao encontrado: $File"
  }
}

New-Item -ItemType Directory -Force -Path $Backup | Out-Null

Write-Host ""
Write-Host "==================================================" -ForegroundColor Cyan
Write-Host "ORCALY - PADRONIZACAO DOS CHECKOUTS" -ForegroundColor Cyan
Write-Host "Cadastro + marketplace no mesmo padrao da assinatura" -ForegroundColor Cyan
Write-Host "==================================================" -ForegroundColor Cyan
Write-Host "A pagina de assinatura nao sera modificada."

$Targets = @(
  "components/checkout/SignupCheckout.tsx",
  "components/checkout/CheckoutClient.tsx",
  "lib/payments/checkout-service.ts"
)

foreach ($Target in $Targets) {
  Backup-File $Target
}

$Files = @{
  "components/checkout/SignupCheckout.tsx" = ""
  "components/checkout/CheckoutClient.tsx" = ""
}

foreach ($Entry in $Files.GetEnumerator()) {
  Write-Base64File $Entry.Key $Entry.Value
}

$PatcherPath = Join-Path $Root ".orcaly-patch-marketplace-brick-$Stamp.cjs"
$PatcherCode = [Text.Encoding]::UTF8.GetString(
  [Convert]::FromBase64String("")
)
[IO.File]::WriteAllText($PatcherPath, $PatcherCode, $Utf8)

try {
  Write-Host ""
  Write-Host "==> Adaptando o marketplace ao Payment Brick" -ForegroundColor Cyan

  & node $PatcherPath

  if ($LASTEXITCODE -ne 0) {
    throw "O patcher nao conseguiu concluir as alteracoes."
  }
} finally {
  Remove-Item -LiteralPath $PatcherPath -Force -ErrorAction SilentlyContinue
}

Write-Host ""
Write-Host "==> Verificando que assinatura nao entrou nas alteracoes" -ForegroundColor Cyan

$SubscriptionDiff = (& git diff --name-only -- "components/subscription/MercadoPagoSubscriptionCheckout.tsx" | Out-String).Trim()

if ($SubscriptionDiff) {
  Write-Host "ATENCAO: a assinatura ja possuia alteracoes locais anteriores." -ForegroundColor Yellow
  Write-Host "Este script nao modificou esse arquivo." -ForegroundColor Yellow
} else {
  Write-Host "[OK] assinatura preservada" -ForegroundColor Green
}

if (-not $SkipBuild) {
  Write-Host ""
  Write-Host "==> Limpando cache do Next" -ForegroundColor Cyan
  Remove-Item -Recurse -Force (Join-Path $Root ".next") -ErrorAction SilentlyContinue

  Write-Host ""
  Write-Host "==> Executando build" -ForegroundColor Cyan

  & npm.cmd run build
  $BuildCode = $LASTEXITCODE

  Write-Host "BUILD_EXIT_CODE=$BuildCode"

  if ($BuildCode -ne 0) {
    Write-Host ""
    Write-Host "O build falhou. Nenhum commit foi criado." -ForegroundColor Red
    Write-Host "Backup: $Backup" -ForegroundColor Yellow
    exit $BuildCode
  }
}

Write-Host ""
Write-Host "==================================================" -ForegroundColor Magenta
Write-Host "CHECKOUTS PADRONIZADOS" -ForegroundColor Magenta
Write-Host "==================================================" -ForegroundColor Magenta
Write-Host "Assinatura: preservada"
Write-Host "Cadastro: mesmo visual e Payment Brick"
Write-Host "Cadastro: Pix + credito com regra dos 7 dias"
Write-Host "Marketplace: mesmo visual e Payment Brick"
Write-Host "Marketplace: Pix + credito + debito"
Write-Host "Marketplace: carrinho, adicionais, entrega e cupom preservados"
Write-Host "Backup: $Backup"
